import rawData from './map-availability.data.json' with { type: 'json' };
import { MAP_LABELS_RU, type MapId } from './maps.ts';
import type { RegionId } from './region-ids.ts';

/**
 * How many places each map has in each region. A map that is missing from the table has places
 * everywhere; a region that is missing under a map has none. The table is generated by
 * `bun run build:map-availability` and a test recomputes it from the datasets.
 */
export interface MapAvailabilityDataset {
  version: 1;
  maps: Partial<Record<MapId, Record<string, number>>>;
}

const dataset = rawData as MapAvailabilityDataset;

/** Places the map has in the region; `Infinity` for a map that covers every region. */
export function countMapPlaces(map: MapId, region: RegionId): number {
  const table = dataset.maps[map];
  if (!table) return Infinity;
  return table[region] ?? 0;
}

export function isMapAvailable(map: MapId, region: RegionId): boolean {
  return countMapPlaces(map, region) > 0;
}

/** Why a match cannot start with this map and region, or null when it can. Shown to the host. */
export function emptyMapRegionReason(
  map: MapId,
  region: RegionId,
  regionLabelRu: string,
): string | null {
  if (isMapAvailable(map, region)) return null;
  return `На карте «${MAP_LABELS_RU[map]}» нет мест в регионе «${regionLabelRu}»: выберите другую карту или регион`;
}
